    private static final int CARD = Color.rgb(0x1B, 0x22, 0x29);
    private static final int ACCENT = Color.rgb(0x6C, 0xC2, 0x3A);
    private static final int TEXT = Color.rgb(0xEC, 0xEF, 0xF1);
