    private boolean autostart;
    private String[] pendingEnv;

    @Override
    protected void onCreate(Bundle state) {
        super.onCreate(state);
        // The app's own shared-storage folders exist once the app asks for
        // them; only then can a zip be placed there over USB or adb (since
        // Android 11 nothing else may create them).
        getObbDir();
        getExternalFilesDir(null);
        setContentView(buildUi());
        handle(getIntent());
    }

    @Override
    protected void onNewIntent(Intent intent) {
        super.onNewIntent(intent);
        setIntent(intent);
        handle(intent);
    }

    @Override
    protected void onResume() {
        super.onResume();
        if (gameStarted) {
            gameStarted = false;
            reportLastRun();
        }
    }

    private void handle(Intent intent) {
        if (intent == null) {
            return;
        }
        pendingEnv = intent.getStringArrayExtra(EXTRA_ENV);
        autostart = intent.getBooleanExtra(EXTRA_AUTOSTART, false);
        if (autostart) {
            start();
        }
    }

