    /** A titled group of radio buttons; each button's tag is its value. */
    private RadioGroup choice(LinearLayout box, String title, String[] values, String[] labels,
                              String current) {
        TextView t = new TextView(this);
        t.setText(title);
        t.setPadding(0, dp(12), 0, dp(2));
        t.setTypeface(Typeface.DEFAULT_BOLD);
        box.addView(t);
        RadioGroup g = new RadioGroup(this);
        g.setOrientation(RadioGroup.VERTICAL);
        for (int i = 0; i < values.length; i++) {
            RadioButton r = new RadioButton(this);
            r.setText(labels[i]);
            r.setTag(values[i]);
            r.setId(View.generateViewId());
            g.addView(r);
            if (values[i].equals(current)) {
                r.setChecked(true);
            }
        }
        box.addView(g);
        return g;
    }

    private static String chosen(RadioGroup g, String def) {
        View v = g.findViewById(g.getCheckedRadioButtonId());
        return v != null && v.getTag() != null ? v.getTag().toString() : def;
    }

    private String[] runtimeEnv() {
        SharedPreferences p = prefs();
        ArrayList<String> env = new ArrayList<>();
        env.add("RECOMP_PRESENT_VSYNC=" + (p.getBoolean("vsync", true) ? "1" : "0"));
        env.add("XBR_TOUCH=" + p.getString("touch", "auto"));
        env.add("RECOMP_ASPECT=" + p.getString("aspect", "4:3"));
        if (p.getBoolean("apu", false)) {
            env.add("RECOMP_AC97_READY=1");
        }
        // Titles read their controllers through the emulated USB host
        // controller (src/usb); off, a game sees none -- not even the
        // on-screen one. Opt-out here; the toolkit's own default is off.
        if (p.getBoolean("usb", true)) {
            env.add("RECOMP_USB=1");
        }
        for (String line : p.getString("extra", "").split("\\s+")) {
            if (line.matches("[A-Z_][A-Z0-9_]*=.*")) {
                env.add(line);
            }
        }
        if (pendingEnv != null) {
            for (String kv : pendingEnv) {
                env.add(kv);
            }
        }
        return env.toArray(new String[0]);
    }

    // ── start ────────────────────────────────────────────────────────────

    private void start() {
        if (busy) {
            return;
        }
        if (GameFiles.installed(this)) {
            launchGame();
            return;
        }
        if (GameFiles.bundled(this)) {
            final long t0 = System.currentTimeMillis();
            runJob(getString(R.string.installing), getString(R.string.install_failed), p -> {
                GameFiles.install(this, p);
                Log.i(TAG, String.format(java.util.Locale.ROOT,
                        "[FILES] installed the game files (%s) from the APK in %.1fs",
                        GameFiles.describe(this), (System.currentTimeMillis() - t0) / 1000.0));
                return null;
            });
            return;
        }
        final File placed = GameFiles.sideloadedZip(this);
        if (placed != null) {
            importFrom(placed.getPath(), () -> new FileInputStream(placed), placed);
            return;
        }
        if (autostart) {
            Log.i(TAG, "[FILES] game files needed: not in the APK, and no game.zip in "
                    + getObbDir() + " or " + getExternalFilesDir(null));
            status.setText(getString(R.string.first_run_external, GameFiles.describe(this)));
            return;
        }
        new AlertDialog.Builder(this)
                .setTitle(getString(R.string.files_needed_title))
                .setMessage(getString(R.string.files_needed, GameFiles.describe(this)))
                .setPositiveButton(getString(R.string.choose_zip), (d, w) -> pickZip())
                .setNegativeButton(android.R.string.cancel, null)
                .show();
    }

    private void pickZip() {
        Intent pick = new Intent(Intent.ACTION_OPEN_DOCUMENT);
        pick.addCategory(Intent.CATEGORY_OPENABLE);
        pick.setType("*/*");
        pick.putExtra(Intent.EXTRA_MIME_TYPES, new String[] {
                "application/zip", "application/x-zip-compressed", "application/octet-stream" });
        try {
            startActivityForResult(pick, REQ_ZIP);
        } catch (Exception e) {
            status.setText(getString(R.string.import_failed) + ": " + e.getMessage());
        }
    }

    @Override
    protected void onActivityResult(int request, int result, Intent data) {
        super.onActivityResult(request, result, data);
        if (request != REQ_ZIP || result != RESULT_OK || data == null || data.getData() == null) {
            return;
        }
        final Uri uri = data.getData();
        importFrom(uri.toString(), () -> getContentResolver().openInputStream(uri), null);
    }

    private interface Source {
        InputStream open() throws Exception;
    }

    /** Import the game files from a zip; placed: a zip in the app's own folder, removed after. */
    private void importFrom(String what, Source source, File placed) {
        Log.i(TAG, "[FILES] importing the game files (" + GameFiles.describe(this) + ") from " + what);
        final long t0 = System.currentTimeMillis();
        runJob(getString(R.string.importing), getString(R.string.import_failed), p -> {
            GameFiles.Imported r;
            try (InputStream in = source.open()) {
                if (in == null) {
                    throw new java.io.IOException("cannot open " + what);
                }
                r = GameFiles.importZip(this, in, p);
            }
            String line = String.format(java.util.Locale.ROOT,
                    "[FILES] imported %d files, %d bytes from %s (%s), each matching its SHA-256,"
                    + " in %.1fs; %d other zip entries ignored", r.files, r.bytes, what,
                    r.folder == null || r.folder.isEmpty() ? "at the zip's root" : "in " + r.folder,
                    (System.currentTimeMillis() - t0) / 1000.0, r.ignored);
            Log.i(TAG, line);
            if (placed != null && placed.delete()) {
                Log.i(TAG, "[FILES] removed " + placed + " (imported)");
            }
            return line;
        });
    }

    private interface Job {
        Object run(GameFiles.Progress p) throws Exception;
    }

    /** Run a file job off the UI thread with progress, then start the game. */
    private void runJob(String label, String failed, Job job) {
        busy = true;
        play.setEnabled(false);
        progress.setVisibility(View.VISIBLE);
        status.setText(label);
        getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
        new Thread(() -> {
            try {
                job.run((done, total, file) -> {
                    final int permille = total > 0 ? (int) (done * 1000 / total) : 0;
                    ui.post(() -> {
                        progress.setProgress(permille);
                        status.setText(String.format("%s  %d%%  %s", label, permille / 10, file));
                    });
                });
                ui.post(() -> {
                    finishJob();
                    status.setText(getString(R.string.ready));
                    launchGame();
                });
            } catch (Exception e) {
                Log.i(TAG, "[FILES] " + failed + ": " + e.getMessage());
                ui.post(() -> {
                    finishJob();
                    status.setText(failed + ": " + e.getMessage());
                    if (!autostart) {
                        new AlertDialog.Builder(this)
                                .setTitle(failed)
                                .setMessage(e.getMessage())
                                .setPositiveButton(android.R.string.ok, null)
                                .show();
                    }
                });
            }
        }, "xbr-files").start();
    }

    private void finishJob() {
        busy = false;
        play.setEnabled(true);
        progress.setVisibility(View.INVISIBLE);
        getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);
    }

    private void launchGame() {
        Intent i = new Intent(this, XbrGameActivity.class);
        i.putExtra(XbrGameActivity.EXTRA_ENV, runtimeEnv());
        gameStarted = true;
        startActivity(i);
    }

    // ── error reporting ──────────────────────────────────────────────────

    private String readLog() {
        File f = GameFiles.logFile(this);
        try (InputStream in = new FileInputStream(f)) {
            return new String(GameFiles.readAll(in), StandardCharsets.UTF_8);
        } catch (Exception e) {
            return null;
        }
    }

    private void reportLastRun() {
        String log = readLog();
        if (log == null) {
            return;
        }
        boolean clean = log.contains("[BOOT] SDL_main returning");
        status.setText(clean ? getString(R.string.ended) : getString(R.string.crashed));
        if (!clean) {
            showLog(getString(R.string.crashed));
        }
    }

    private void showLog(String heading) {
        String log = readLog();
        if (log == null) {
            log = getString(R.string.no_log);
        }
        String[] lines = log.split("\n");
        StringBuilder tail = new StringBuilder();
        for (int i = Math.max(0, lines.length - 80); i < lines.length; i++) {
            tail.append(lines[i]).append('\n');
        }
        final String text = tail.toString();
        TextView tv = new TextView(this);
        tv.setText(text);
        tv.setTypeface(Typeface.MONOSPACE);
        tv.setTextSize(TypedValue.COMPLEX_UNIT_SP, 11);
        tv.setTextIsSelectable(true);
        tv.setPadding(dp(16), dp(8), dp(16), dp(8));
        ScrollView sv = new ScrollView(this);
        sv.addView(tv);
        sv.post(() -> sv.fullScroll(View.FOCUS_DOWN));
        new AlertDialog.Builder(this)
                .setTitle(heading)
                .setView(sv)
                .setPositiveButton(android.R.string.ok, null)
                .setNeutralButton(getString(R.string.share), (d, w) -> {
                    Intent send = new Intent(Intent.ACTION_SEND);
                    send.setType("text/plain");
                    send.putExtra(Intent.EXTRA_SUBJECT, getString(R.string.app_name) + " log");
                    send.putExtra(Intent.EXTRA_TEXT, text);
                    startActivity(Intent.createChooser(send, getString(R.string.share)));
                })
                .show();
    }
